
package com.store.productservice.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*; @ControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,String>> handleValidation(MethodArgumentNotValidException ex){ Map<String,String> errors=new HashMap<>(); ex.getBindingResult().getFieldErrors().forEach(e->errors.put(e.getField(),e.getDefaultMessage())); return new ResponseEntity<>(errors,HttpStatus.BAD_REQUEST);} @ExceptionHandler(ResourceNotFoundException.class) public ResponseEntity<Map<String,String>> handleNotFound(ResourceNotFoundException ex){ Map<String,String> body=new HashMap<>(); body.put("error",ex.getMessage()); return new ResponseEntity<>(body,HttpStatus.NOT_FOUND);} @ExceptionHandler(Exception.class) public ResponseEntity<Map<String,String>> handleOther(Exception ex){ Map<String,String> body=new HashMap<>(); body.put("error","Erreur interne: "+ex.getMessage()); return new ResponseEntity<>(body,HttpStatus.INTERNAL_SERVER_ERROR);} }
